import{c as a,Q as t,j as o,m as i}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Guide","description":"","frontmatter":{"title":"Guide","outline":"deep"},"headers":[],"relativePath":"en/guide.md","filePath":"en/guide.md","lastUpdated":1794895051000}'),n={name:"en/guide.md"};function s(r,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>This page describes FMCL&#39;s interface and usage following the actual workflow. For the feature list and edge cases, see <a href="/en/features">Features</a>; for what configuration options mean, see <a href="/en/config">Configuration</a>.</p><h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><ol><li>FMCL shows a splash screen at startup, then checks the runtime environment (data directory, Java, graphics backend).</li><li>On the first run it asks for a language, then for the terms of use and the announcement; after you agree, the main window opens.</li><li>The left side of the main window is the top-level navigation, grouped as &quot;Game / Resources and Multiplayer / Tools and Extensions&quot;; domains unavailable on the current platform (such as installed Bedrock Edition on non-Windows) do not appear.</li><li>The right side of the top bar holds search, announcements, update checks and Settings; the bottom status bar shows task progress and operation results.</li></ol><h2 id="installing-a-game-version" tabindex="-1">Installing a Game Version <a class="header-anchor" href="#installing-a-game-version" aria-label="Permalink to &quot;Installing a Game Version&quot;">​</a></h2><ol><li>Open &quot;Installed versions&quot; in the left navigation and click &quot;Install new version&quot;.</li><li>Enter a version ID (such as <code>1.20.4</code>), or switch to the &quot;Release / Snapshot&quot; tabs and click an entry to fill it in (20 per page).</li><li>Choose a mod loader: none, Forge, Fabric, NeoForge, Quilt, LiteLoader, LegacyFabric, Cleanroom or OptiFine. When a loader is selected, vanilla Minecraft installs in parallel and the compatibility of that loader with the game version is checked automatically.</li><li>Click &quot;Install version&quot;; the progress card shows overall progress, the current file, download speed and remaining items, and can be cancelled at any time.</li><li>When installation finishes, return to the version list and refresh to see the new instance.</li></ol><blockquote><p>Once the loader is installed, version isolation is enabled for that instance, creating separate <code>mods/</code>, <code>config/</code>, <code>saves/</code> and similar directories. On networks in China it is recommended to keep the China mirror enabled in Settings; the mirror covers version manifests, game assets, libraries and loader installers.</p></blockquote><h2 id="launching-the-game" tabindex="-1">Launching the Game <a class="header-anchor" href="#launching-the-game" aria-label="Permalink to &quot;Launching the Game&quot;">​</a></h2><ol><li>Open &quot;Game&quot; in the left navigation and click &quot;Launch game&quot; on the &quot;Recently used version&quot; card, or select an instance under &quot;Installed versions&quot; and launch it.</li><li>Java is checked before launch: system Java is scanned and version-matched automatically by default; it can also be specified in Settings → Java.</li><li>While the game runs, the button becomes &quot;Force quit game&quot;, which ends that process.</li><li>Once the game window appears, the launcher minimizes or not according to Settings, and closes the stdout pipe so the final loading stage is not slowed down.</li></ol><p>A non-zero exit code, or a crash report / <code>hs_err</code> file written after this launch, opens the crash diagnostics window: view the exit code, the crash report, the game log and the JVM crash log, export a diagnostics ZIP, upload the log to LogShare.CN, or sign in to a Jingdu account for AI analysis.</p><h2 id="managing-installed-versions" tabindex="-1">Managing Installed Versions <a class="header-anchor" href="#managing-installed-versions" aria-label="Permalink to &quot;Managing Installed Versions&quot;">​</a></h2><ul><li>Version rows offer details, mods, resources, rename, delete and open directory.</li><li>Renaming updates the folder name, the version JSON file name and the internal <code>id</code> together; existing resources are not lost.</li><li>Deletion asks for confirmation first and clears the &quot;recently used version&quot; record.</li><li>Verification checks instance file integrity with concurrent hashing and writes the result back to the page.</li></ul><h2 id="resource-management" tabindex="-1">Resource Management <a class="header-anchor" href="#resource-management" aria-label="Permalink to &quot;Resource Management&quot;">​</a></h2><p>After selecting an instance, open &quot;Mods&quot; or &quot;Resource management&quot; to manage four resource types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Extensions</th><th>Install directory</th></tr></thead><tbody><tr><td>Mods</td><td><code>.jar</code> <code>.zip</code>, <code>.jar.disabled</code> when disabled</td><td><code>mods/</code></td></tr><tr><td>Resource packs</td><td><code>.zip</code></td><td><code>resourcepacks/</code></td></tr><tr><td>Worlds</td><td><code>.zip</code> extracted automatically, or a folder</td><td><code>saves/</code></td></tr><tr><td>Shader packs</td><td><code>.zip</code></td><td><code>shaderpacks/</code></td></tr></tbody></table><ul><li>Installation: drag files onto the window, or click &quot;Install from file&quot;.</li><li>Mod cards read metadata from the jar (icon, name, author, modid, version); resource packs and shader packs extract preview images from the zip.</li><li>Typed search, pagination, enable and disable, delete, open directory, and copying the mod list to the clipboard.</li><li>&quot;Check for updates&quot; queries Modrinth and CurseForge at the same time, allows a batch update after selection, and keeps finished files for failed items.</li></ul><blockquote><p>Vanilla instances show only resource packs and worlds; mods and shader packs appear once a mod loader is installed, consistent with the version isolation rules.</p></blockquote><h2 id="browsing-online-resources" tabindex="-1">Browsing Online Resources <a class="header-anchor" href="#browsing-online-resources" aria-label="Permalink to &quot;Browsing Online Resources&quot;">​</a></h2><p>Open &quot;Browse resources&quot; in the left navigation:</p><ol><li>Popular content loads on entry; the type can be switched between mods, resource packs and shader packs.</li><li>Filter by keyword, game version and mod loader; the game version and loader are prefilled from the current instance.</li><li>Cards show name, author, download count and description; open the details to choose a specific version, preview dependencies and install into a chosen instance.</li><li>Installation resolves <code>required</code> dependencies recursively; a missing compatible version is skipped with a notice.</li><li>Without <code>CURSEFORGE_API_KEY</code> only Modrinth is queried; after signing in to a Jingdu account, AI search can expand the keywords.</li></ol><h2 id="installing-a-modpack" tabindex="-1">Installing a Modpack <a class="header-anchor" href="#installing-a-modpack" aria-label="Permalink to &quot;Installing a Modpack&quot;">​</a></h2><p>Under &quot;Installed versions&quot; → &quot;Install new version&quot; → &quot;Install modpack&quot;:</p><ol><li>Choose a source: a local <code>.mrpack</code> / MultiMC / CurseForge / HMCL / MCBBS / generic archive, or click &quot;Download from online browse&quot;.</li><li>The program parses metadata, optional components and the component list; optional files in <code>.mrpack</code> can be selected.</li><li>A custom instance name can be set (the modpack name by default; conflicting or invalid names disable the start button).</li><li>Click &quot;Start installation&quot; and wait for the parallel phase and the loader installation to finish.</li><li>The version list refreshes automatically when installation finishes; launch directly or open resource management.</li></ol><blockquote><p>A custom instance name generates that instance&#39;s own version JSON, and the version list, launch and resource management all identify the instance by it; this is also why modpack instances with custom names are recognized correctly.</p></blockquote><h2 id="servers" tabindex="-1">Servers <a class="header-anchor" href="#servers" aria-label="Permalink to &quot;Servers&quot;">​</a></h2><h3 id="installation-and-launch" tabindex="-1">Installation and Launch <a class="header-anchor" href="#installation-and-launch" aria-label="Permalink to &quot;Installation and Launch&quot;">​</a></h3><ol><li>Open &quot;Servers&quot; in the left navigation and click &quot;Install server&quot;.</li><li>Enter a version ID, or pick one from the release list (10 per page).</li><li>When installation finishes, click start in the server list; several servers can run at once.</li><li>The first start generates a basic <code>server.properties</code> and accepts the EULA; offline mode is used by default.</li><li>Each server can set its own maximum memory (1G to 16G), stored in <code>.fmcl_server.json</code> in that server&#39;s directory.</li></ol><p>When a port is taken, the launcher moves on to a free port, writes it back to the configuration and reports the actual port in the list and on the detail page.</p><h3 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h3><p>The console on the server detail page shows running state, online players and a memory sample every 2 seconds; logs scroll to the bottom automatically and keep at most 5000 lines. The command box at the bottom sends on Enter or with the button, and can also clear the screen and export logs.</p><h3 id="configuration-editor" tabindex="-1">Configuration Editor <a class="header-anchor" href="#configuration-editor" aria-label="Permalink to &quot;Configuration Editor&quot;">​</a></h3><p>Click a server row or the configuration button on the detail page to edit <code>server.properties</code> in 7 categories:</p><ul><li>Search by name, key (such as <code>motd</code>) or description; each entry shows its name, raw key and a one-line description.</li><li>Numeric entries show their valid range and are highlighted in red with a dialog when out of range.</li><li>Saving only updates the keys that changed and keeps comments and unknown keys; entries or whole categories can be restored to defaults.</li><li>The &quot;Raw file&quot; category edits the text directly; the page guards against leaving with unsaved changes.</li></ul><h3 id="hosting-from-a-modpack" tabindex="-1">Hosting from a Modpack <a class="header-anchor" href="#hosting-from-a-modpack" aria-label="Permalink to &quot;Hosting from a Modpack&quot;">​</a></h3><p>Next to &quot;Install server&quot; under &quot;Servers&quot; you can host a server from a modpack, which accepts <code>.mrpack</code> only. Installation detects the Forge / Fabric / NeoForge / Quilt server loader automatically, installs Fabric API automatically when a Fabric server lacks it, and lists mods of unknown purpose after installation so each can be disabled.</p><h2 id="terracotta-multiplayer" tabindex="-1">Terracotta Multiplayer <a class="header-anchor" href="#terracotta-multiplayer" aria-label="Permalink to &quot;Terracotta Multiplayer&quot;">​</a></h2><p>Windows only. On first entry it detects EasyTier and guides you through installing it (several mirrors are speed-tested, with automatic fallback).</p><p>Creating a lobby:</p><ol><li>Enter the local Minecraft port (25565 by default) and a display name.</li><li>Click &quot;Create lobby&quot;; it is ready in about 5 seconds.</li><li>Send the generated Terracotta code (<code>U/</code> prefix, 21 characters) to your friends.</li></ol><p>Joining a lobby:</p><ol><li>Enter the code and a display name, then click &quot;Join lobby&quot;.</li><li>Once connected, connect to <code>localhost</code> in Minecraft multiplayer.</li><li>The member list shows the host first, and the latency to the host is shown at the bottom in real time.</li></ol><p>The &quot;Scan&quot; button discovers shared worlds on the same LAN; it only lists results and never joins automatically.</p><h2 id="world-save-backups" tabindex="-1">World Save Backups <a class="header-anchor" href="#world-save-backups" aria-label="Permalink to &quot;World Save Backups&quot;">​</a></h2><p>Open &quot;Saves&quot; in the left navigation:</p><ol><li>The page scans the global <code>saves/</code> directory and each isolated instance directory automatically and rescans on refresh.</li><li>Select a save and click &quot;Back up&quot;; a note can be added and the compression progress is real.</li><li>The backup list shows time, size, game version and note, and supports restore, verify, export ZIP and delete.</li><li>ZIP integrity is verified before a restore; by default the current save is renamed to <code>_bak_&lt;timestamp&gt;</code> and kept.</li><li>The bottom of the page has toggles for &quot;Back up before the game starts&quot; and &quot;Back up after the game exits&quot;; toggles are written to the configuration immediately.</li></ol><p>Settings can change the backup path, compression level (1 / 3 / 6 / 9), retention per save (5 / 10 / 20 / 30 / 50 / unlimited) and how the old save is handled on restore.</p><h2 id="music" tabindex="-1">Music <a class="header-anchor" href="#music" aria-label="Permalink to &quot;Music&quot;">​</a></h2><p>Open &quot;Music&quot; in the left navigation; the &quot;Discover&quot; home page shows daily recommendations, recommended playlists, charts and new music.</p><ul><li><strong>Local music</strong>: choose a folder to recursively scan MP3 / FLAC / OGG / WAV / M4A / AAC, read tags and embedded cover art, and &quot;play all&quot;.</li><li><strong>Online search</strong>: queries NetEase Cloud Music, QQ Music, Kuwo, Kugou and Migu at once, with Bilibili as a cross-source fallback; the highest available quality is chosen automatically.</li><li><strong>Playlists</strong>: all songs, liked music, recently played, user playlists and NetEase Cloud playlists; sorting and &quot;play all&quot; are supported.</li><li><strong>Lyrics</strong>: LRC, translations and romanization; desktop lyrics scroll in three lines and support locking, unlocked dragging and opacity adjustment.</li><li><strong>Hotkeys</strong>: <code>Ctrl+Shift+Space</code> play and pause, <code>Ctrl+Shift+Left/Right</code> previous and next, <code>Ctrl+Shift+Down</code> stop, <code>Ctrl+Shift+Up/PageDown</code> volume, <code>Ctrl+Shift+Alt+M</code> mute.</li></ul><p>When playback fails it searches the same track across sources automatically and uses a duration check to filter out covers and instrumentals; on Windows system media control (SMTC) is also supported.</p><h2 id="toolbox" tabindex="-1">Toolbox <a class="header-anchor" href="#toolbox" aria-label="Permalink to &quot;Toolbox&quot;">​</a></h2><p>Open &quot;Tools&quot; in the left navigation. Nine small tools: game junk cleanup, port check, hash calculation, coordinate conversion, today&#39;s luck, fun facts, knowledge quiz, multithreaded download and related sites.</p><p>Performance monitor: press <code>Ctrl+Shift+M</code> or click the monitor button in the top bar to open the floating window, which shows CPU, memory and GPU data, can be dragged and remembers its position.</p><h2 id="achievements-and-daily-check-in" tabindex="-1">Achievements and Daily Check-in <a class="header-anchor" href="#achievements-and-daily-check-in" aria-label="Permalink to &quot;Achievements and Daily Check-in&quot;">​</a></h2><p>Open &quot;Achievement overview&quot; in the left navigation to see the overall progress of 47 achievements across 9 categories, with progress and stage on each card. Unlocks show a notification in the bottom-right corner; the home page shows the consecutive daily check-in streak. After signing in to a Jingdu account, the &quot;Cloud&quot; category can sync saves.</p><h2 id="agent-and-voice" tabindex="-1">AGENT and Voice <a class="header-anchor" href="#agent-and-voice" aria-label="Permalink to &quot;AGENT and Voice&quot;">​</a></h2><p>Open &quot;AGENT&quot; in the left navigation:</p><ol><li>The session list on the left can create, switch, rename and delete sessions; history is saved automatically.</li><li>Describe what you need in the input box, for example &quot;install the Fabric version of 1.20.4 for me&quot;.</li><li>Tool calls show their arguments and results; high-risk commands, file modifications and questions all require confirmation, and file writes, edits and deletes preview a diff first.</li><li>The provider and model can be chosen at the top right; Settings → AI configures the API key, endpoint, thinking intensity and tool permissions.</li></ol><p>Pressing Enter in the top quick input jumps to AGENT and sends the message. The voice button next to the input uses the offline SenseVoice model for voice input, and the model downloads automatically on first use.</p><p>The command line works as well:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;install the latest version for me&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span></code></pre></div><h2 id="bedrock-edition" tabindex="-1">Bedrock Edition <a class="header-anchor" href="#bedrock-edition" aria-label="Permalink to &quot;Bedrock Edition&quot;">​</a></h2><p>Windows 10 19041 or later only. Open &quot;Installed Bedrock&quot; in the left navigation:</p><ol><li>Search the version catalog or filter by UWP / GDK, 20 entries per page.</li><li>The first installation requires accepting the MCAPPX terms; GDK checks for the .NET 10 SDK and provides download guidance.</li><li>Installation uses real progress and resume, and the version can be launched directly afterwards.</li><li>Installed cards support launch, delete, details and opening the version directory.</li></ol><h2 id="settings-and-accounts" tabindex="-1">Settings and Accounts <a class="header-anchor" href="#settings-and-accounts" aria-label="Permalink to &quot;Settings and Accounts&quot;">​</a></h2><h3 id="settings-sections" tabindex="-1">Settings Sections <a class="header-anchor" href="#settings-sections" aria-label="Permalink to &quot;Settings Sections&quot;">​</a></h3><p>Open &quot;Settings&quot; in the left navigation; 9 sections in total: launcher, Java, theme, music account, logs, about, accounts, AI and plugins. Edits first go into a draft and can preview themes and languages, and are written only when you save; leaving with unsaved changes prompts.</p><h3 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h3><ul><li><strong>Microsoft</strong>: PKCE OAuth by default, with device code sign-in as an alternative.</li><li><strong>Offline</strong>: a UUID is generated locally, no network needed.</li><li><strong>Yggdrasil</strong>: <code>authlib-injector</code> is injected automatically when connecting to third-party authentication servers such as skin sites.</li></ul><p>Accounts can be added, deleted, switched and set as current, and encrypted <code>.fmcl_accounts</code> files can be imported and exported. The player name comes from the current account.</p><h3 id="themes-and-languages" tabindex="-1">Themes and Languages <a class="header-anchor" href="#themes-and-languages" aria-label="Permalink to &quot;Themes and Languages&quot;">​</a></h3><p>The theme section offers 5 presets, importing a <code>.json</code> theme, a custom <code>#RRGGBB</code> accent color and a version-based dynamic theme. Languages are Simplified Chinese, English, Traditional Chinese and Japanese, switched immediately.</p><h2 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h2><p>Open the plugin manager from &quot;Settings&quot; → &quot;Plugins&quot;:</p><ol><li>&quot;Install from file&quot; selects a <code>.fmpl</code> plugin package, or browse the plugin marketplace and install with one click.</li><li>The list shows name, version, author and state, and plugins can be enabled, disabled, uninstalled and inspected for permissions.</li><li>Enabling and disabling both hot-reload without a restart; high-risk permissions prompt on every use.</li><li>Plugins that provide QML pages appear in the &quot;Plugins&quot; group at the bottom of the sidebar.</li></ol><p>See the <a href="/en/plugin">plugin development guide</a> for details.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>On Windows the launcher checks for updates at startup (this can be disabled in Settings). A new version shows its version number and changelog, and Settings → About can check manually, download and launch the installer.</p><p>Linux and macOS have no automatic installation: on Linux use the one-click setup script or download the tarball again; on macOS update from source.</p>`,79)])])}const g=a(n,[["render",s]]);export{p as __pageData,g as default};
